# ─────────────────────────────────────────────────────────────────────────
# Grafana teams + folder permissions — access control
# ─────────────────────────────────────────────────────────────────────────
# Default SSO users tienen Viewer org role (grafana.ini auto_assign_org_role),
# pero NO tienen acceso a ningún folder por default — los folder_permission
# de abajo strippean la inheritance del Viewer role.
#
# Pattern aplicado:
#   - Admin role           → Admin   (stays)
#   - Editor role          → Edit    (stays)
#   - Viewer role          → (sin entry) → acceso revocado
#   - developers team      → View    (solo en infra-monitoring)
#
# Resultado:
#   - Viewer por default ve 0 dashboards → pantalla vacía al loguearse
#   - Members del team developers ven SOLO Infrastructure Monitoring
#   - KPI Dashboards queda restringido a Admin/Editor del org
# ─────────────────────────────────────────────────────────────────────────

resource "grafana_team" "developers" {
  name  = "developers"
  email = "developers@liftit.co"
}

resource "grafana_folder_permission" "infra" {
  folder_uid = grafana_folder.infra.uid

  permissions {
    role       = "Admin"
    permission = "Admin"
  }
  permissions {
    role       = "Editor"
    permission = "Edit"
  }
  permissions {
    team_id    = grafana_team.developers.id
    permission = "View"
  }
  # NOTE: sin entry para role=Viewer → Viewer default pierde acceso al folder.
}

resource "grafana_folder_permission" "kpi" {
  folder_uid = grafana_folder.kpi.uid

  permissions {
    role       = "Admin"
    permission = "Admin"
  }
  permissions {
    role       = "Editor"
    permission = "Edit"
  }
  # Sin team developers + sin Viewer → KPI Dashboards solo admin/editor.
}

resource "grafana_folder_permission" "engineering_kpis" {
  folder_uid = grafana_folder.engineering_kpis.uid

  permissions {
    role       = "Admin"
    permission = "Admin"
  }
  permissions {
    role       = "Editor"
    permission = "Edit"
  }
  # Sin team developers + sin Viewer → Engineering KPIs solo admin/editor.
  # Contiene los 42 dashboards de DevLake (DORA, Jira, GitHub, etc.) que
  # originalmente iban a moverse desde General, pero son provisioned
  # (DevLake los gestiona via YAML file provisioning) — la API rechaza
  # moverlos. Solución aplicada abajo: restringir el folder General mismo.
}

# Restringir el folder General — bloquea Viewers de ver dashboards
# provisioned ahí (42 dashboards DevLake). Grafana 10+ permite ACL sobre
# General; el uid es literalmente "general".
resource "grafana_folder_permission" "general" {
  folder_uid = "general"

  permissions {
    role       = "Admin"
    permission = "Admin"
  }
  permissions {
    role       = "Editor"
    permission = "Edit"
  }
  # Sin entry Viewer role + sin team developers → Viewers (default SSO)
  # no ven los 42 provisioned dashboards en General.
}

